#!/usr/bin/env bash
# Question 3: PersistentVolumeClaim ${Q3_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q3_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q3_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q3_NAME}-pv
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce, ReadWriteMany]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q3_NAME}
    type: DirectoryOrCreate
EOF
kubectl patch pv "${Q3_NAME}-pv" -p '{"spec": {"capacity": {"storage": "2Gi"}}}'
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q3_NAME}-pv-old
  labels: { tier: legacy }
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce, ReadWriteMany]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q3_NAME}-old
    type: DirectoryOrCreate
EOF
kubectl label pv "${Q3_NAME}-pv" tier="${Q3_SELECT_TIER}" --overwrite
